// Lit ce qui arrive (alerte Railway, ou log envoyé par n'importe quel hébergeur ou CI)
// et décide s'il faut l'analyser.
const r = $('Réglages').first().json;
const item = $input.first().json;
const body = (item.body && typeof item.body === 'object') ? item.body : {};
const max = Math.min(Math.max(Number(r.lignes_de_log) || 300, 20), 1000);
const suivis = String(r.projets_suivis || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const horsSuivi = p => suivis.length && p && !suivis.includes(String(p).toLowerCase());

// 1. Un log envoyé directement : champ log (texte) ou lines (liste).
if ('log' in body || 'lines' in body || 'service' in body) {
  let lignes = [];
  if (Array.isArray(body.lines)) lignes = body.lines.map(l => String((l && typeof l === 'object') ? (l.message || '') : l));
  else if (typeof body.log === 'string') lignes = body.log.split(/\r?\n/);
  while (lignes.length && !lignes[lignes.length - 1].trim()) lignes.pop();
  lignes = lignes.slice(-max);
  const projet = String(body.projet || body.project || '');
  const suivre = !horsSuivi(projet);
  return [{ json: {
    source: 'direct', suivre,
    raison: suivre ? 'log envoyé par un hébergeur ou une CI' : `projet ${projet} absent de projets_suivis`,
    type: '', statut: String(body.statut || body.status || 'FAILED').toUpperCase(), deploymentId: '',
    projet, service: String(body.service || ''), environnement: String(body.environnement || body.environment || ''),
    commit: String(body.commit || '').slice(0, 7), message_commit: String(body.message_commit || '').split('\n')[0].slice(0, 80),
    date: String(body.date || ''), lignes, erreurs: [],
  } }];
}

// 2. Une alerte Railway (webhook du projet).
const details = body.details || {};
const res = body.resource || {};
const type = String(body.type || '');
const statut = String(details.status || '').toUpperCase();
const projet = String((res.project || {}).name || '');
const projetId = String((res.project || {}).id || '');
const deploymentId = String((res.deployment || {}).id || details.id || '');
const annonce = /\.(crashed|failed)$/i.test(type) || ['CRASHED', 'FAILED'].includes(statut);

let suivre = true;
let raison = 'panne annoncée par Railway';
if (!annonce) {
  suivre = false;
  raison = `événement ${type || 'sans type'} (${statut || 'sans statut'}) : pas une panne annoncée`;
} else if (horsSuivi(projet) && horsSuivi(projetId)) {
  suivre = false;
  raison = `projet ${projet || projetId} absent de projets_suivis`;
} else if (!deploymentId) {
  suivre = false;
  raison = "l'événement ne donne pas l'identifiant du déploiement";
}

return [{ json: {
  source: 'railway', suivre, raison, type, statut, deploymentId, projet,
  service: String((res.service || {}).name || ''),
  environnement: String((res.environment || {}).name || ''),
  commit: String(details.commitHash || '').slice(0, 7),
  message_commit: String(details.commitMessage || '').split('\n')[0].slice(0, 80),
  date: String(body.timestamp || ''),
  graphql: {
    query: 'query deploymentLogs($deploymentId: String!, $limit: Int) { deploymentLogs(deploymentId: $deploymentId, limit: $limit) { timestamp message } }',
    variables: { deploymentId, limit: max },
  },
} }];

// Range la réponse de l'API Railway dans la même forme qu'un log envoyé directement.
const ev = { ...$("Lire l'entrée").first().json };
delete ev.graphql;
const body = $input.first().json || {};
const logs = ((body.data || {}).deploymentLogs) || [];
const erreurs = body.errors || (body.error ? [body.error] : []);
return [{ json: { ...ev, lignes: logs.map(l => String((l && l.message) || '')), erreurs } }];

// Nomme la cause de la panne à partir des logs du déploiement.
// Mêmes signatures que le skill deploy-doctor (claude/deploy-doctor).
// Entrée : les champs de l'événement, lignes (liste de textes) et erreurs.
const ev = $input.first().json || {};
const erreurs = ev.erreurs || [];
const lignes = (ev.lignes || []).map((t, i) => ({ n: i + 1, texte: String(t) }));
const railway = ev.source === 'railway';

const REGLES = [
  { id: 'npm-pid1-sigterm', titre: 'npm transforme un redéploiement normal en panne',
    motifs: [/npm (?:error|ERR!) signal SIGTERM/, /ELIFECYCLE.*SIGTERM/, /(?:yarn|pnpm).*(?:SIGTERM|exit code 143)/],
    cause: "Le conteneur démarre par npm (ou yarn, pnpm). À chaque redéploiement, l'hébergeur envoie SIGTERM ; npm le déclare en échec et sort avec un code non nul. L'hébergeur annonce une panne alors que l'app s'est arrêtée normalement.",
    correctif: 'Démarre le serveur avec node directement (Dockerfile : CMD ["node", "dist/server.js"]) et gère SIGTERM : ferme le serveur, puis sors avec le code 0.',
    verifier: "Redéploie deux fois : le log de l'ancien conteneur finit sans « npm error », et plus aucune alerte n'arrive." },
  { id: 'python-not-found', titre: "la commande appelle python, l'image n'a que python3",
    motifs: [/\bpython: command not found/, /\/bin\/(?:ba)?sh: \d+: python: not found/, /exec: "python": executable file not found/],
    cause: "La commande de démarrage ou le cron appelle « python », mais l'image ne fournit que « python3 ». Le service meurt avant d'exécuter une ligne.",
    correctif: "Appelle python3 dans la commande de démarrage ou du cron (ou installe le paquet python-is-python3 dans l'image).",
    verifier: 'Lance le cron une fois à la main : il affiche sa propre sortie, pas « command not found ».' },
  { id: 'missing-env-var', titre: "une variable d'environnement obligatoire manque",
    motifs: [/KeyError: '([A-Z][A-Z0-9_]{2,})'/, /ImproperlyConfigured: Set the ([A-Z][A-Z0-9_]+) environment variable/, /[Mm]issing (?:required )?environment variable:? ['"]?([A-Z][A-Z0-9_]+)/],
    cause: "Le code lit {var} sans valeur par défaut et la variable n'existe pas sur ce service : l'app plante au démarrage.",
    correctif: 'Ajoute {var} sur chaque service qui exécute ce code (web, worker, cron), puis redéploie. Ne colle sa valeur ni dans un chat ni dans un log.',
    verifier: 'Liste les variables du service et vérifie que {var} y est (valeur masquée), puis redéploie : le log atteint la ligne où le serveur écoute.' },
  { id: 'dev-settings-in-prod', titre: 'la production tourne avec les réglages de développement',
    motifs: [/you have DEBUG = True in your Django settings/, /Watching for file changes with StatReloader/, /Starting development server at/],
    cause: "L'app déployée tourne en réglages de développement (DEBUG actif, souvent une base SQLite jetable) : le module de réglages dépend d'une variable absente sur l'hébergeur.",
    correctif: 'Fixe DJANGO_SETTINGS_MODULE sur le module de production pour chaque service, ou dans la commande de démarrage. Ajoute d\'abord ALLOWED_HOSTS : des réglages de production qui la lisent sans défaut plantent au démarrage.',
    verifier: "Demande une page qui n'existe pas : tu dois voir un simple 404, pas la page de débogage." },
  { id: 'port-binding', titre: 'le serveur écoute sur localhost, le proxy ne le joint pas',
    motifs: [/(?:[Ll]istening|running|Running) (?:on|at):? (?:https?:\/\/)?(?:127\.0\.0\.1|localhost)(?::\d+)?/, /Listening at: https?:\/\/(?:127\.0\.0\.1|localhost)/],
    cause: "Le serveur écoute sur localhost dans le conteneur. Le proxy de l'hébergeur ne peut pas le joindre : chaque requête finit en 502 « Application failed to respond ».",
    correctif: "Écoute sur 0.0.0.0 et sur le port de la variable PORT (uvicorn --host 0.0.0.0 --port $PORT ; Express : app.listen(process.env.PORT, '0.0.0.0')).",
    verifier: "Après le redéploiement, le log affiche 0.0.0.0 et la valeur de PORT, et l'adresse publique répond." },
  { id: 'out-of-memory', titre: 'le processus a manqué de mémoire',
    motifs: [/JavaScript heap out of memory/, /Reached heap limit/, /exit(?:ed with)? code:? 137\b/, /OOMKilled/, /\bMemoryError\b/, /^\s*Killed\s*$/],
    cause: "Le processus a dépassé sa limite de mémoire et a été tué (le code 137 correspond à SIGKILL). Les dernières lignes avant l'arrêt montrent ce qui tournait.",
    correctif: 'Repère le pic dans les métriques de mémoire, puis baisse-le (moins de workers, des lots plus petits, NODE_OPTIONS=--max-old-space-size pour Node) ou relève la limite du service.',
    verifier: "Rejoue la même charge après le redéploiement : la mémoire reste sous la limite et aucun code 137 n'apparaît." },
  { id: 'migrations-not-applied', titre: 'le schéma de la base est en retard sur le code',
    motifs: [/relation "([^"]+)" does not exist/, /no such table: (\w+)/, /column "[^"]+" (?:of relation "[^"]+" )?does not exist/, /You have \d+ unapplied migration/],
    cause: "Le code attend une table ou une colonne que cette base n'a pas : les migrations n'ont pas été appliquées sur cet environnement.",
    correctif: 'Lance les migrations pendant le déploiement (commande de pré-déploiement, par exemple python manage.py migrate), puis redéploie.',
    verifier: "python manage.py showmigrations (ou l'équivalent de ton outil) ne liste aucune migration en attente, et la requête qui échouait passe." },
  { id: 'missing-dependency', titre: 'une dépendance manque dans le build',
    motifs: [/ModuleNotFoundError: No module named '([\w.]+)'/, /Error: Cannot find module '([^']+)'/, /ImportError: No module named ([\w.]+)/],
    cause: "Le code importe {var}, que le build n'a pas installé : il manque dans requirements.txt ou package.json (ou il n'est que dans devDependencies).",
    correctif: 'Ajoute {var} au fichier de dépendances utilisé par le build, commite, redéploie.',
    verifier: 'Le log du build installe {var}, et le démarrage passe l\'import.' },
];
const ARRET_PROPRE = [/Received SIGTERM/, /SIGTERM received/, /Handling signal: term/, /[Gg]raceful(?:ly)? (?:shutdown|stopping)/, /[Ss]hutting down/];

const trouvees = [];
for (const regle of REGLES) {
  for (const l of lignes) {
    const m = regle.motifs.map(rx => l.texte.match(rx)).find(Boolean);
    if (!m) continue;
    const v = m[1] || '';
    const remplir = s => s.split('{var}').join(v);
    trouvees.push({ id: regle.id, titre: remplir(regle.titre), variable: v, ligne: l.n,
      preuve: l.texte.trim().slice(0, 160), cause: remplir(regle.cause),
      correctif: remplir(regle.correctif), verifier: remplir(regle.verifier) });
    break;
  }
}
const arret = trouvees.length ? null : lignes.find(l => ARRET_PROPRE.some(rx => rx.test(l.texte)));

const ou = [ev.service || 'service inconnu', ev.projet && `projet ${ev.projet}`, ev.environnement && `environnement ${ev.environnement}`].filter(Boolean).join(', ');
const entete = [
  `Service : ${ou}`,
  ev.commit ? `Commit : ${ev.commit}${ev.message_commit ? ` (${ev.message_commit})` : ''}` : '',
  railway ? `Annoncé par Railway : ${ev.statut || '?'} (${ev.type || 'sans type'})${ev.date ? `, le ${ev.date}` : ''}` : `Log envoyé par ton hébergeur ou ta CI${ev.date ? `, le ${ev.date}` : ''}`,
].filter(Boolean).join('\n');
const fin = `${lignes.length ? `Lu par crash-triage (n8n) sur ${lignes.length} lignes de log. ` : ''}Pour la ligne de code qui provoque la panne, lance deploy-doctor dans Claude Code et dis « mon déploiement a planté ».`;
const queue = lignes.slice(-15).map(l => `${l.n}: ${l.texte}`).join('\n');

let verdict, cause_id = '', titre, texte;
if (erreurs.length) {
  verdict = 'inconnue'; titre = 'Railway a refusé la lecture des logs';
  texte = `${entete}\n\nLa panne est annoncée, mais Railway a refusé la lecture des logs : ${String((erreurs[0] || {}).message || erreurs[0]).slice(0, 200)}\nVérifie le jeton Railway du nœud « Logs du déploiement (Railway) ».\n\n${fin}`;
} else if (trouvees.length) {
  const f = trouvees[0];
  verdict = 'panne'; cause_id = f.id; titre = f.titre;
  const autres = trouvees.slice(1).map(t => `- ${t.titre} (ligne ${t.ligne})`).join('\n');
  texte = `${entete}\n\nCause : ${f.titre}\nPreuve, ligne ${f.ligne} du log : ${f.preuve}\n\nPourquoi : ${f.cause}\nCorrectif : ${f.correctif}\nPour vérifier : ${f.verifier}` +
    (autres ? `\n\nAutres signatures dans le même log :\n${autres}` : '') + `\n\n${fin}`;
} else if (arret) {
  verdict = 'arret-normal'; titre = 'arrêt normal sur SIGTERM';
  texte = `${entete}\n\nArrêt normal, ligne ${arret.n} : ${arret.texte.trim().slice(0, 160)}. Rien à corriger.`;
} else if (!lignes.length) {
  verdict = 'inconnue'; titre = 'aucune ligne de log';
  texte = railway
    ? `${entete}\n\nLa panne est annoncée, mais Railway ne rend aucune ligne de log pour ce déploiement. Si la panne a eu lieu pendant le build, ouvre le log de build dans Railway.\n\n${fin}`
    : `${entete}\n\nLa requête ne contenait aucune ligne de log : envoie le champ log (texte) ou lines (liste).\n\n${fin}`;
} else {
  verdict = 'inconnue'; titre = 'cause non reconnue';
  texte = `${entete}\n\nAucune des 8 pannes connues ne correspond, et rien ne montre un arrêt normal. Les ${Math.min(15, lignes.length)} dernières lignes du log :\n\n${queue}\n\n${fin}`;
}
const sujet = `${railway ? 'Railway' : 'Déploiement'} : panne annoncée sur ${ev.service || 'ton service'}, ${verdict === 'panne' ? 'cause : ' : ''}${titre}`;

return [{ json: { verdict, cause_id, titre, sujet, texte, a_alerter: verdict !== 'arret-normal',
  lignes_lues: lignes.length, signatures: trouvees.map(t => t.id) } }];
